function CvssForgePure(){
  // ============ CVSS v3.1 权重表（FIRST.org 官方规范 §7）============
  var W31 = {
    AV:{N:0.85, A:0.62, L:0.55, P:0.2},
    AC:{L:0.77, H:0.44},
    PR_U:{N:0.85, L:0.62, H:0.27},
    PR_C:{N:0.85, L:0.68, H:0.50},
    UI:{N:0.85, R:0.62},
    CIA:{H:0.56, L:0.22, N:0},
    E:{X:1, H:1, F:0.97, P:0.94, U:0.91},
    RL:{X:1, U:1, W:0.97, T:0.96, O:0.95},
    RC:{X:1, C:1, R:0.96, U:0.92},
    CIAR:{X:1, H:1.5, M:1, L:0.5}
  };
  var LABEL31 = {
    AV:{N:'网络 Network', A:'邻接网络 Adjacent', L:'本地 Local', P:'物理 Physical'},
    AC:{L:'低 Low', H:'高 High'},
    PR:{N:'无 None', L:'低 Low', H:'高 High'},
    UI:{N:'无需交互 None', R:'需要交互 Required'},
    S:{U:'未改变 Unchanged', C:'已改变 Changed'},
    C:{H:'高 High', L:'低 Low', N:'无 None'},
    I:{H:'高 High', L:'低 Low', N:'无 None'},
    A:{H:'高 High', L:'低 Low', N:'无 None'},
    E:{X:'未定义', H:'已成熟 High', F:'功能性 Functional', P:'概念验证 PoC', U:'未证实 Unproven'},
    RL:{X:'未定义', U:'不可用 Unavailable', W:'临时方案 Workaround', T:'临时补丁 Temporary', O:'官方补丁 Official'},
    RC:{X:'未定义', C:'已确认 Confirmed', R:'有理有据 Reasonable', U:'未知 Unknown'},
    CR:{X:'未定义', H:'高', M:'中', L:'低'}
  };
  var BASE_KEYS = ['AV','AC','PR','UI','S','C','I','A'];
  var ALLOWED31 = {
    AV:'NALP', AC:'LH', PR:'NLH', UI:'NR', S:'UC', C:'HLN', I:'HLN', A:'HLN',
    E:'XHFPU', RL:'XUWTO', RC:'XCRU',
    CR:'XHML', IR:'XHML', AR:'XHML',
    MAV:'XNALP', MAC:'XLH', MPR:'XNLH', MUI:'XNR', MS:'XUC', MC:'XHLN', MI:'XHLN', MA:'XHLN'
  };

  // CVSS v3.1 官方 Roundup：避免二进制浮点导致的边界误差
  function roundup(x){
    var i = Math.round(x * 100000);
    if (i % 10000 === 0) return i / 100000.0;
    return (Math.floor(i / 10000) + 1) / 10.0;
  }
  function round1(x){ return Math.round(x * 10) / 10; }

  function severity(score){
    if (score <= 0) return '无 None';
    if (score < 4) return '低 Low';
    if (score < 7) return '中 Medium';
    if (score < 9) return '高 High';
    return '严重 Critical';
  }

  function parseVector(vec){
    var s = String(vec || '').trim();
    if (!s) return {error:'请输入 CVSS 向量串'};
    var parts = s.split('/').filter(function(x){ return x !== ''; });
    var version = null, m = {};
    for (var i = 0; i < parts.length; i++){
      var kv = parts[i].split(':');
      if (kv.length !== 2) return {error:'片段格式错误：' + parts[i] + '（应为 KEY:VALUE）'};
      var k = kv[0], v = kv[1];
      if (k === 'CVSS'){ version = v; continue; }
      if (m.hasOwnProperty(k)) return {error:'重复的指标：' + k};
      m[k] = v;
    }
    return {error:null, version:version, metrics:m};
  }

  // ---------------- v3.1 ----------------
  function score31(m){
    for (var i = 0; i < BASE_KEYS.length; i++){
      var k = BASE_KEYS[i];
      if (!m[k]) return {error:'缺少必需的基础指标：' + k};
      if (ALLOWED31[k].indexOf(m[k]) < 0) return {error:'指标 ' + k + ' 的取值非法：' + m[k]};
    }
    var opt = ['E','RL','RC','CR','IR','AR','MAV','MAC','MPR','MUI','MS','MC','MI','MA'];
    for (var j = 0; j < opt.length; j++){
      var ok = opt[j];
      if (m[ok] && ALLOWED31[ok].indexOf(m[ok]) < 0)
        return {error:'指标 ' + ok + ' 的取值非法：' + m[ok]};
    }
    var scopeChanged = (m.S === 'C');
    var prTable = scopeChanged ? W31.PR_C : W31.PR_U;

    var iscBase = 1 - ((1 - W31.CIA[m.C]) * (1 - W31.CIA[m.I]) * (1 - W31.CIA[m.A]));
    var impact = scopeChanged
      ? (7.52 * (iscBase - 0.029) - 3.25 * Math.pow(iscBase - 0.02, 15))
      : (6.42 * iscBase);
    var expl = 8.22 * W31.AV[m.AV] * W31.AC[m.AC] * prTable[m.PR] * W31.UI[m.UI];

    var base;
    if (impact <= 0) base = 0;
    else base = roundup(Math.min(scopeChanged ? 1.08 * (impact + expl) : (impact + expl), 10));

    var e = W31.E[m.E || 'X'], rl = W31.RL[m.RL || 'X'], rc = W31.RC[m.RC || 'X'];
    var temporal = roundup(base * e * rl * rc);

    // 环境分：未定义（X）的修正指标回落到对应基础指标
    function md(key, baseKey){
      var v = m['M' + key];
      if (!v || v === 'X') return m[baseKey || key];
      return v;
    }
    var mAV = md('AV'), mAC = md('AC'), mPR = md('PR'), mUI = md('UI'), mS = md('S');
    var mC = md('C'), mI = md('I'), mA = md('A');
    var cr = W31.CIAR[m.CR || 'X'], ir = W31.CIAR[m.IR || 'X'], ar = W31.CIAR[m.AR || 'X'];
    var mScopeChanged = (mS === 'C');
    var mPrTable = mScopeChanged ? W31.PR_C : W31.PR_U;

    var mIscBase = Math.min(
      1 - ((1 - W31.CIA[mC] * cr) * (1 - W31.CIA[mI] * ir) * (1 - W31.CIA[mA] * ar)), 0.915);
    var mImpact = mScopeChanged
      ? (7.52 * (mIscBase - 0.029) - 3.25 * Math.pow(mIscBase * 0.9731 - 0.02, 13))
      : (6.42 * mIscBase);
    var mExpl = 8.22 * W31.AV[mAV] * W31.AC[mAC] * mPrTable[mPR] * W31.UI[mUI];

    var env;
    if (mImpact <= 0) env = 0;
    else {
      var raw = roundup(Math.min(mScopeChanged ? 1.08 * (mImpact + mExpl) : (mImpact + mExpl), 10));
      env = roundup(raw * e * rl * rc);
    }

    return {
      error:null, version:'3.1',
      base:base, temporal:temporal, environmental:env,
      impactSub:round1(impact < 0 ? 0 : impact), exploitability:round1(expl),
      baseSeverity:severity(base), temporalSeverity:severity(temporal), envSeverity:severity(env),
      scopeChanged:scopeChanged, metrics:m
    };
  }

  // ---------------- v2.0（NVD 遗留数据仍在广泛使用）----------------
  var W20 = {
    AV:{L:0.395, A:0.646, N:1.0},
    AC:{H:0.35, M:0.61, L:0.71},
    Au:{M:0.45, S:0.56, N:0.704},
    CIA:{N:0, P:0.275, C:0.660}
  };
  function score20(m){
    var need = ['AV','AC','Au','C','I','A'];
    for (var i = 0; i < need.length; i++){
      if (!m[need[i]]) return {error:'CVSS v2 缺少必需指标：' + need[i]};
    }
    if (!W20.AV[m.AV] && W20.AV[m.AV] !== 0) return {error:'AV 取值非法：' + m.AV};
    if (!W20.AC[m.AC]) return {error:'AC 取值非法：' + m.AC};
    if (!W20.Au[m.Au]) return {error:'Au 取值非法：' + m.Au};
    var cc = W20.CIA[m.C], ii = W20.CIA[m.I], aa = W20.CIA[m.A];
    if (cc === undefined || ii === undefined || aa === undefined)
      return {error:'C/I/A 取值非法（应为 N/P/C）'};
    var impact = 10.41 * (1 - (1 - cc) * (1 - ii) * (1 - aa));
    var expl = 20 * W20.AV[m.AV] * W20.AC[m.AC] * W20.Au[m.Au];
    var f = (impact === 0) ? 0 : 1.176;
    var base = round1(((0.6 * impact) + (0.4 * expl) - 1.5) * f);
    return {
      error:null, version:'2.0', base:base,
      impactSub:round1(impact), exploitability:round1(expl),
      baseSeverity:(base < 4 ? '低 Low' : base < 7 ? '中 Medium' : '高 High'),
      metrics:m
    };
  }

  // ---------------- v4.0 向量语法校验（评分表未内置，仅做结构体检）----------------
  var V40_BASE = ['AV','AC','AT','PR','UI','VC','VI','VA','SC','SI','SA'];
  var V40_ALLOWED = {
    AV:'NALP', AC:'LH', AT:'NP', PR:'NLH', UI:'NPA',
    VC:'HLN', VI:'HLN', VA:'HLN', SC:'HLN', SI:'HLN', SA:'HLN',
    E:'XAPU', CR:'XHML', IR:'XHML', AR:'XHML',
    MAV:'XNALP', MAC:'XLH', MAT:'XNP', MPR:'XNLH', MUI:'XNPA',
    MVC:'XHLN', MVI:'XHLN', MVA:'XHLN', MSC:'XHLN', MSI:'XHLNS', MSA:'XHLNS',
    S:'XNP', AU:'XNY', R:'XAUI', V:'XDC', RE:'XLMH', U:'X,Clear,Green,Amber,Red'
  };
  function check40(m){
    var issues = [];
    for (var i = 0; i < V40_BASE.length; i++){
      if (!m[V40_BASE[i]]) issues.push({level:'err', text:'缺少 v4.0 必需基础指标：' + V40_BASE[i]});
    }
    for (var k in m){
      if (!m.hasOwnProperty(k)) continue;
      var al = V40_ALLOWED[k];
      if (!al){ issues.push({level:'warn', text:'未知的 v4.0 指标：' + k}); continue; }
      if (al.indexOf(',') >= 0){
        if (al.split(',').indexOf(m[k]) < 0) issues.push({level:'err', text:k + ' 取值非法：' + m[k]});
      } else if (al.indexOf(m[k]) < 0){
        issues.push({level:'err', text:k + ' 取值非法：' + m[k]});
      }
    }
    // 命名法（CVSS-B / BT / BE / BTE）
    var hasT = !!(m.E && m.E !== 'X');
    var envKeys = ['CR','IR','AR','MAV','MAC','MAT','MPR','MUI','MVC','MVI','MVA','MSC','MSI','MSA'];
    var hasE = false;
    for (var j = 0; j < envKeys.length; j++){ if (m[envKeys[j]] && m[envKeys[j]] !== 'X') hasE = true; }
    var nomen = 'CVSS-B';
    if (hasT && hasE) nomen = 'CVSS-BTE';
    else if (hasT) nomen = 'CVSS-BT';
    else if (hasE) nomen = 'CVSS-BE';
    return {error:null, version:'4.0', nomenclature:nomen, issues:issues, metrics:m};
  }

  function buildVector(m, version){
    var order = (version === '2.0')
      ? ['AV','AC','Au','C','I','A','E','RL','RC','CDP','TD','CR','IR','AR']
      : ['AV','AC','PR','UI','S','C','I','A','E','RL','RC','CR','IR','AR',
         'MAV','MAC','MPR','MUI','MS','MC','MI','MA'];
    var out = (version === '2.0') ? [] : ['CVSS:' + (version || '3.1')];
    for (var i = 0; i < order.length; i++){
      var k = order[i];
      if (m[k] && m[k] !== 'X') out.push(k + ':' + m[k]);
    }
    return out.join('/');
  }

  function analyze(vec){
    var p = parseVector(vec);
    if (p.error) return {error:p.error};
    var m = p.metrics, v = p.version;
    var r;
    if (v === '4.0') r = check40(m);
    else if (v === '2.0' || (!v && m.Au)) r = score20(m);
    else r = score31(m);
    if (r.error) return {error:r.error};
    r.vector = buildVector(m, r.version);
    r.labels = LABEL31;
    return r;
  }

  var api = {parseVector:parseVector, score31:score31, score20:score20, check40:check40,
             analyze:analyze, buildVector:buildVector, roundup:roundup, severity:severity,
             LABEL31:LABEL31, W31:W31};
  if (typeof window !== 'undefined'){ window.__PURE__ = api; }
  if (typeof module !== 'undefined' && module.exports){ module.exports = {CvssForgePure:CvssForgePure}; }
  return api;
}
